'use client';

import {useState,useEffect,useRef,useCallback,type ReactNode,type FormEvent} from 'react';
import {ArrowLeft,ArrowUpLeft,ArrowRight,Camera,Search,SlidersHorizontal,Heart,MapPin,Check,ChevronDown,ChevronLeft,X,Plus,Menu,Video,Clapperboard,LayoutDashboard,MessageCircle,FileText,Calendar,Send,CheckCircle2,Play,Clock,ShieldCheck,Briefcase,User,LogOut,Settings,ExternalLink,RefreshCw,Sparkles,ShoppingBag,Coffee,Palette,Image as ImageIcon,Loader2,Bookmark,Download} from 'lucide-react';
import {creators,categories,cities,packages,stages,statusLabels,emptyWorkspace,money,type Creator,type Campaign,type Workspace} from '../lib/catalog';

type UserInfo={name:string;email:string}|null;
type Toast={message:string;error?:boolean};
type View='home'|'dashboard'|'saved'|'settings'|'admin';
type Modal='campaign'|'join'|'auth'|'terms'|'privacy'|null;
const icons=[Sparkles,ShoppingBag,Coffee,Palette,Camera];
const dateLabel=(v:string|number)=>new Intl.DateTimeFormat('ar-PS',{day:'numeric',month:'long',year:'numeric'}).format(new Date(v));

export default function Platform({user}:{user:UserInfo}){
 const[view,setView]=useState<View>('home');
 const[modal,setModal]=useState<Modal>(null);
 const[selectedCreator,setSelectedCreator]=useState<Creator|null>(null);
 const[selectedCampaign,setSelectedCampaign]=useState<Campaign|null>(null);
 const[packageId,setPackageId]=useState('story');
 const[preferredCreator,setPreferredCreator]=useState<string|null>(null);
 const[workspace,setWorkspace]=useState<Workspace>(emptyWorkspace);
 const[loading,setLoading]=useState(!!user);
 const[loadError,setLoadError]=useState('');
 const[toast,setToast]=useState<Toast|null>(null);
 const[query,setQuery]=useState('');
 const[mobileMenu,setMobileMenu]=useState(false);
 const[localFavorites,setLocalFavorites]=useState<string[]>([]);
 const notify=useCallback((message:string,error=false)=>setToast({message,error}),[]);
 const refresh=useCallback(async()=>{
  if(!user)return;
  setLoading(true);setLoadError('');
  try{const r=await fetch('/api/workspace',{cache:'no-store'});const data=await r.json() as Workspace & {error?:string};if(!r.ok)throw new Error(data.error);setWorkspace(data);}
  catch(e){setLoadError(e instanceof Error?e.message:'تعذّر الاتصال. حاول مجددًا.');}
  finally{setLoading(false);}
 },[user]);
 useEffect(()=>{void refresh();},[refresh]);
 useEffect(()=>{const change=()=>{const hash=location.hash.slice(1);setView(['dashboard','saved','settings','admin'].includes(hash)?hash as View:'home');setMobileMenu(false);if(hash==='join')setModal('join');if(hash==='campaign'){try{const d=JSON.parse(sessionStorage.getItem('loqtah-brief')||'null');if(d&&packages.some(p=>p.id===d.packageId)){setPackageId(d.packageId);setPreferredCreator(d.creatorId||null);}}catch{}setModal('campaign');}};change();window.addEventListener('hashchange',change);try{setLocalFavorites(JSON.parse(localStorage.getItem('loqtah-saved')||'[]'));}catch{}return()=>window.removeEventListener('hashchange',change);},[]);
 useEffect(()=>{if(toast){const t=setTimeout(()=>setToast(null),4500);return()=>clearTimeout(t);}},[toast]);
 function navigate(section:string){
  location.hash=section;
  setView(['dashboard','saved','settings','admin'].includes(section)?section as View:'home');setMobileMenu(false);
  if(['dashboard','saved','settings','admin','home'].includes(section))window.scrollTo({top:0,behavior:'smooth'});
  else setTimeout(()=>document.getElementById(section)?.scrollIntoView({behavior:'smooth',block:'start'}),80);
 }
 async function mutate(data:Record<string,unknown>){
  if(!user){setModal('auth');throw new Error('سجّل دخولك لإتمام الخطوة.');}
  const response=await fetch('/api/workspace',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});
  const result=await response.json() as {error?:string;ok?:boolean;id?:string};if(!response.ok)throw new Error(result.error||'تعذّر الحفظ.');
  await refresh();return result;
 }
 const saved=user?workspace.favorites:localFavorites;
 async function toggleFavorite(id:string){
  const next=!saved.includes(id);
  if(user){try{await mutate({action:'favorite',creatorId:id,saved:next});notify(next?'أُضيف إلى قائمتك المحفوظة.':'أُزيل من قائمتك.');}catch(e){notify((e as Error).message,true);}}
  else{const result=next?[...localFavorites,id]:localFavorites.filter(v=>v!==id);setLocalFavorites(result);localStorage.setItem('loqtah-saved',JSON.stringify(result));notify(next?'حُفظ على هذا الجهاز. سجّل دخولك للحفظ في حسابك.':'أُزيل من قائمتك.');}
 }
 function startCampaign(id='story',creatorId:string|null=null){setPackageId(id);setPreferredCreator(creatorId);setSelectedCreator(null);setModal('campaign');}
 return <>
  <a href="#main" className="skip-link">انتقل إلى المحتوى</a>
  <header className="header">
   <div className="container header-inner">
    <button className="brand" onClick={()=>navigate('home')} aria-label="لقطة، الرئيسية"><Brand/></button>
    <nav className={mobileMenu?'navigation is-open':'navigation'} aria-label="القائمة الرئيسية">
     <button className={view==='home'?'nav-link active':'nav-link'} onClick={()=>navigate('creators')}>اكتشف المواهب</button>
     <button className="nav-link" onClick={()=>navigate('how')}>كيف تعمل لقطة؟</button>
     <button className="nav-link" onClick={()=>navigate('packages')}>الباقات</button>
     <button className={view==='dashboard'?'nav-link active':'nav-link'} onClick={()=>navigate('dashboard')}>لوحة حملاتي</button>
    </nav>
    <div className="header-actions">
     <button className="icon-btn saved-top" aria-label={`المحفوظات، ${saved.length}`} onClick={()=>navigate('saved')}><Heart size={20}/>{saved.length>0&&<i>{saved.length}</i>}</button>
     <button className="account-btn" onClick={()=>user?navigate('settings'):setModal('auth')}>{user?<><span className="mini-avatar">{(workspace.profile?.name||user.name).slice(0,1)}</span><span>حسابي</span></>:<span>تسجيل الدخول</span>}</button>
     <button className="btn btn-dark header-cta" onClick={()=>startCampaign()}>ابدأ حملتك <ArrowUpLeft size={16}/></button>
     <button className="icon-btn menu-btn" aria-expanded={mobileMenu} aria-label="فتح القائمة" onClick={()=>setMobileMenu(!mobileMenu)}>{mobileMenu?<X/>:<Menu/>}</button>
    </div>
   </div>
  </header>
  <main id="main">
  {view==='home'?<>
   <section className="hero container" id="home">
    <div className="hero-copy">
     <div className="eyebrow"><span className="live-dot"/> حكايات محلية. أثر أكبر.</div>
     <h1>علامتك تستاهل<br/>تنشاف <span className="hero-highlight">بلقطة أحلى.<svg viewBox="0 0 310 18" aria-hidden="true"><path d="M4 13Q147-5 305 8M20 17Q158 2 291 13"/></svg></span></h1>
     <p className="hero-description">اجمع الفكرة الصح، والموهبة المناسبة، والتنفيذ المرتّب.<br className="desktop-break"/> من أول فكرة لآخر تعديل، حملتك كلها بمكان واحد.</p>
     <div className="hero-buttons"><button className="btn btn-coral btn-lg" onClick={()=>startCampaign()}>خلّينا نصنع إعلانك <ArrowUpLeft size={19}/></button><button className="btn btn-outline btn-lg" onClick={()=>navigate('creators')}><span className="small-play"><Play size={12} fill="currentColor"/></span> اكتشف المواهب</button></div>
     <div className="hero-assurance"><span><CheckCircle2 size={15}/> تفاصيل واضحة قبل التنفيذ</span><span><CheckCircle2 size={15}/> المحتوى بموافقتك</span></div>
    </div>
    <div className="hero-art" aria-label="مساحة إبداع تجمع صناع المحتوى والمنتجات">
     <span className="art-ring ring-one"/><span className="art-ring ring-two"/>
     <div className="photo-main"><img src="/images/creator-lina.jpg" alt="صورة توضيحية لصانعة محتوى" fetchPriority="high"/><div className="photo-shade"/><span className="photo-category"><Camera size={14}/> شغف يتحوّل لمحتوى</span><div className="photo-caption"><span>التفاصيل الصغيرة،<br/><b>تصنع الفرق الكبير.</b></span><span className="round-arrow"><ArrowUpLeft/></span></div></div>
     <div className="photo-small"><img src="/images/coffee.jpg" alt="تفاصيل فنجان قهوة لتصوير إعلان مقهى"/><span><span className="live-dot"/> حكاية تبدأ من هون</span></div>
     <span className="floating-spark"><Sparkles size={32} strokeWidth={1.6}/></span>
     <div className="floating-note"><span className="note-check"><Check size={19}/></span><div><b>من الفكرة… للتسليم.</b><small>إبداع كثير. تعقيد أقل.</small></div><span className="note-line"/></div>
     <span className="art-label" dir="ltr">MAKE IT A <b>LOQTAH.</b></span>
    </div>
   </section>
   <div className="value-strip"><div className="container value-strip-inner"><span className="strip-label">فريق واحد. كل التفاصيل.</span><span><Clapperboard/> إنتاج محتوى</span><span><User/> مواهب محلية</span><span><FileText/> موافقات واضحة</span><span><Calendar/> تسليم منظّم</span><span className="strip-end"><span className="live-dot"/> نبدأ من فلسطين</span></div></div>
   <section className="discovery-section container" id="creators">
    <div className="section-heading"><div><span className="overline">الموهبة بتفرق</span><h2>وجوه مبدعة. <span className="serif-accent">حكايات مختلفة.</span></h2><p>اعثر على الأسلوب اللي يشبه علامتك، وخلّي الباقي علينا.</p></div><button className="text-link" onClick={()=>setModal('join')}>أنت صانع محتوى؟ انضم للقطة <ArrowUpLeft size={17}/></button></div>
    <Explorer query={query} setQuery={setQuery} saved={saved} onSave={toggleFavorite} onOpen={setSelectedCreator}/>
   </section>
   <section className="how-section" id="how"><div className="container">
    <div className="section-heading"><div><span className="overline">خلّيها بسيطة</span><h2>من «عندي فكرة»<br/>لـ «جاهز للنشر».</h2></div><p className="section-intro">تركيزك على شغلك.<br/>وتفاصيل إعلانك علينا، خطوة بخطوة.</p></div>
    <div className="how-grid">{[
     {n:'01',icon:FileText,title:'احكيلنا عن علامتك',body:'حدّد هدفك، ميزانيتك، ونوع المحتوى. حتى لو الفكرة لسه مش كاملة.'},
     {n:'02',icon:Camera,title:'نرتّب المشهد سوا',body:'نراجع الطلب، نتفق على الفريق والخطة والتكلفة، وبعد موافقتك نبدأ.'},
     {n:'03',icon:CheckCircle2,title:'راجع. وافق. انشر.',body:'تابع التقدّم، اكتب ملاحظاتك، واستلم المحتوى المتفق عليه جاهزًا للنشر.'},
    ].map(item=><article className="how-card" key={item.n}><div className="how-top"><span>{item.n}</span><item.icon size={26} strokeWidth={1.5}/></div><h3>{item.title}</h3><p>{item.body}</p></article>)}</div>
   </div></section>
   <section className="packages-section container" id="packages"><div className="section-heading centered"><div><span className="overline">لكل بداية لقطة</span><h2>اختر المساحة المناسبة <span className="serif-accent">لإبداعك.</span></h2><p>باقات مقترحة تساعدك تخطّط. العرض النهائي يتحدد بعد مراجعة طلبك.</p></div></div><div className="packages-grid">{packages.map((p,i)=><article className={`package-card ${i===1?'featured':''}`} key={p.id}>{i===1&&<span className="package-ribbon"><Sparkles size={13}/> توازن بين الفكرة والتنوّع</span>}<span className="overline">{p.tag}</span><h3>{p.name}</h3><p>{p.description}</p><div className="price"><small>تقديريًا من</small><strong>{money(p.price)}<span> ₪</span></strong><small>{i===2?'/ شهريًا':'/ للحملة'}</small></div><button className={`btn ${i===1?'btn-coral':'btn-outline'}`} onClick={()=>startCampaign(p.id)}>ابدأ بهذه الباقة <ArrowUpLeft size={16}/></button><div className="package-divider"/><ul>{p.features.map(f=><li key={f}><Check size={17}/>{f}</li>)}</ul></article>)}</div><p className="pricing-note">الأسعار استرشادية وليست عرضًا ملزمًا. أتعاب المواهب، التنقّل، وميزانية الإعلانات المموّلة تُحدَّد بشكل منفصل في العرض النهائي.</p></section>
   <section className="creative-banner container"><div className="banner-visual"><img src="/images/studio.jpg" alt="كاميرا في مساحة عمل إبداعية" loading="lazy"/><span className="banner-stamp"><Sparkles size={28}/><b>صُنع بشغف.</b></span></div><div className="banner-copy"><span className="overline">الموهبة عندك. والفرصة نخلقها سوا.</span><h2>وراء كل علامة قوية،<br/>شخص عنده <span>حكاية.</span></h2><p>بتصوّر، بتمنتج، أو بتحب تكون قدّام الكاميرا؟<br/>خلّي شغلك يحكي عنك، وانضم لشبكة لقطة.</p><button className="btn btn-dark" onClick={()=>setModal('join')}>قدّم كصانع محتوى <ArrowUpLeft size={17}/></button></div></section>
   <FAQ/>
   <section className="final-cta"><div className="container"><div><span className="overline">المشهد الجاي إلك</span><h2>عندك علامة.<br/>خلّينا نصنع إلها <span>لقطة.</span></h2></div><div><p>ما بدك فكرة كاملة لتبدأ.<br/>بدك خطوة أولى وبس.</p><button className="btn btn-coral btn-lg" onClick={()=>startCampaign()}>ابدأ حكايتك معنا <ArrowUpLeft size={20}/></button></div></div><span className="cta-star" aria-hidden="true">✳</span></section>
  </>:view==='saved'?<section className="container workspace-page"><Breadcrumb title="المحفوظات" home={()=>navigate('home')}/><div className="section-heading"><div><span className="overline">قائمتك الإبداعية</span><h1 className="page-title">مواهب لفتت انتباهك.</h1><p>{user?'قائمتك محفوظة في حسابك.':'قائمتك محفوظة على هذا الجهاز. سجّل دخولك لحفظ قائمتك في حسابك.'}</p></div><span className="count-badge">{saved.length} مواهب</span></div>{saved.length?<div className="creator-grid">{creators.filter(c=>saved.includes(c.id)).map(c=><CreatorCard key={c.id} creator={c} saved onSave={toggleFavorite} onOpen={setSelectedCreator}/>)}</div>:<Empty icon={<Bookmark/>} title="لسه ما حفظت أي موهبة" description="تصفّح الأساليب المختلفة، واضغط القلب على الملف اللي يعجبك." action={()=>navigate('creators')} actionText="اكتشف المواهب"/>}</section>
  :view==='settings'?<SettingsView user={user} workspace={workspace} mutate={mutate} notify={notify} auth={()=>setModal('auth')}/>
  :view==='admin'?<AdminView enabled={workspace.isAdmin} notify={notify}/>
  :<Dashboard user={user} workspace={workspace} loading={loading} error={loadError} refresh={refresh} onNew={()=>startCampaign()} onOpen={setSelectedCampaign} navigate={navigate} auth={()=>setModal('auth')}/>}
  </main>
  <footer className="footer"><div className="container footer-top"><div className="footer-brand"><button className="brand" onClick={()=>navigate('home')}><Brand/></button><p>أفكار محلية. محتوى يترك أثر.<br/>من أول فكرة لآخر لقطة.</p></div><div><h3>استكشف لقطة</h3><button onClick={()=>navigate('creators')}>المواهب</button><button onClick={()=>navigate('packages')}>الباقات</button><button onClick={()=>navigate('how')}>كيف تعمل لقطة؟</button></div><div><h3>مساحتك</h3><button onClick={()=>navigate('dashboard')}>حملاتي</button><button onClick={()=>navigate('saved')}>المحفوظات</button><button onClick={()=>setModal('join')}>انضم كصانع محتوى</button></div><div className="footer-message"><span className="live-dot"/><h3>من فلسطين، بكل شغف.</h3><p>نسخة أولية قيد التطوير.<br/>نبني مساحة أرحب للإبداع المحلي.</p></div></div><div className="container footer-bottom"><span>© {new Date().getFullYear()} لقطة. لكل حكاية بداية.</span><div><button onClick={()=>setModal('privacy')}>الخصوصية</button><button onClick={()=>setModal('terms')}>شروط الاستخدام</button><span dir="ltr">MADE TO CREATE ↗</span></div></div></footer>
  {selectedCreator&&<CreatorModal creator={selectedCreator} saved={saved.includes(selectedCreator.id)} onSave={toggleFavorite} onClose={()=>setSelectedCreator(null)} onStart={()=>startCampaign('story',selectedCreator.id)}/>}
  {modal==='campaign'&&<CampaignWizard packageId={packageId} creatorId={preferredCreator} user={user} profile={workspace.profile} mutate={mutate} onClose={()=>setModal(null)} onDone={()=>{setModal(null);navigate('dashboard');notify('تم إرسال طلب حملتك. ستظهر أي تحديثات في لوحة حملاتك.');}}/>}
  {modal==='join'&&<JoinForm user={user} application={workspace.application} mutate={mutate} onClose={()=>setModal(null)} onDone={()=>{setModal(null);notify('تم استلام طلب انضمامك للمراجعة.');navigate('dashboard');}}/>}
  {modal==='auth'&&<ModalShell title="أهلًا في لقطة." subtitle="مساحتك الإبداعية، على بُعد خطوة." onClose={()=>setModal(null)}><div className="auth-content"><span className="auth-icon"><Camera size={32}/></span><p>سجّل دخولك لتحفظ مواهبك المفضلة، ترسل طلباتك، وتتابع كل تفاصيل حملاتك.</p><a className="btn btn-dark btn-lg full" href="/signin-with-chatgpt?return_to=/%23dashboard" target="_top">المتابعة باستخدام ChatGPT <ArrowUpLeft size={18}/></a><small>تسجيل الدخول آمن عبر ChatGPT. لا نطلب كلمة مرورك.</small></div></ModalShell>}
  {(modal==='privacy'||modal==='terms')&&<LegalModal kind={modal} onClose={()=>setModal(null)}/>}
  {selectedCampaign&&<CampaignDetail campaign={workspace.campaigns.find(c=>c.id===selectedCampaign.id)||selectedCampaign} workspace={workspace} mutate={mutate} onClose={()=>setSelectedCampaign(null)} notify={notify}/>}
  {toast&&<div className={`toast ${toast.error?'error':''}`} role="status">{toast.error?<X size={18}/>:<CheckCircle2 size={18}/>}<span>{toast.message}</span><button aria-label="إغلاق التنبيه" onClick={()=>setToast(null)}><X size={15}/></button></div>}
 </>;
}

function Brand(){return <><span className="brand-mark"><svg viewBox="0 0 36 36" fill="none" aria-hidden="true"><path d="M12 5H6a1 1 0 0 0-1 1v6m19-7h6a1 1 0 0 1 1 1v6M5 24v6a1 1 0 0 0 1 1h6m12 0h6a1 1 0 0 0 1-1v-6" stroke="currentColor" strokeWidth="3" strokeLinecap="round"/><path d="m13 11 12 7-12 7V11Z" fill="currentColor"/></svg></span><span className="brand-word">لقطة<span dir="ltr">LOQTAH</span></span></>}

function Explorer({query,setQuery,saved,onSave,onOpen}:{query:string;setQuery:(s:string)=>void;saved:string[];onSave:(id:string)=>void;onOpen:(c:Creator)=>void}){
 const[category,setCategory]=useState('الكل');const[city,setCity]=useState('');const[expanded,setExpanded]=useState(false);const[filters,setFilters]=useState(false);
 const filtered=creators.filter(c=>(category==='الكل'||category===c.category)&&(!city||city===c.city)&&(!query||[c.name,c.city,c.role,...c.skills].join(' ').includes(query.trim())));
 return <><div className="search-toolbar"><div className="search-box"><Search size={20}/><input aria-label="ابحث عن موهبة أو مجال" placeholder="مين الموهبة اللي بتدور عليها؟" value={query} onChange={e=>{setQuery(e.target.value);setExpanded(true);}}/>{query&&<button className="icon-btn" aria-label="مسح البحث" onClick={()=>setQuery('')}><X size={16}/></button>}</div><label className="city-filter"><MapPin size={17}/><select aria-label="المدينة" value={city} onChange={e=>{setCity(e.target.value);setExpanded(true);}}><option value="">كل المدن</option>{cities.map(c=><option key={c}>{c}</option>)}</select><ChevronDown size={14}/></label><button className={`filter-btn ${filters?'on':''}`} aria-label="تصفية المواهب" aria-expanded={filters} onClick={()=>setFilters(!filters)}><SlidersHorizontal size={18}/><span>تصفية</span>{(city||category!=='الكل')&&<i/>}</button></div>
 {filters&&<div className="filter-panel"><span>التصفية حسب المدينة والمجال متاحة أدناه.</span><button className="text-link" onClick={()=>{setCity('');setCategory('الكل');setQuery('');}}>إعادة ضبط <RefreshCw size={14}/></button></div>}
 <div className="category-tabs" role="group" aria-label="مجال المحتوى">{categories.map((c,i)=>{const Icon=icons[i];return <button key={c} aria-pressed={category===c} className={category===c?'selected':''} onClick={()=>{setCategory(c);setExpanded(true);}}><Icon size={16}/>{c}</button>})}</div>
 <div className="results-caption"><span>{filtered.length} مواهب للاستكشاف</span><span><span className="tiny-dot"/> ملفات توضيحية لتجربة المنصة</span></div>
 {filtered.length?<div className="creator-grid">{filtered.slice(0,expanded?6:4).map(c=><CreatorCard key={c.id} creator={c} saved={saved.includes(c.id)} onSave={onSave} onOpen={onOpen}/>)}</div>:<Empty icon={<Search/>} title="ما لقينا نتيجة بهالمواصفات" description="جرّب مجالًا ثانيًا أو امسح المدينة لتوسّع البحث." action={()=>{setQuery('');setCategory('الكل');setCity('');}} actionText="عرض كل المواهب"/>}
 {!expanded&&filtered.length>4&&<div className="center-action"><button className="btn btn-outline" onClick={()=>setExpanded(true)}>شوف كل المواهب <ArrowLeft size={17}/></button></div>}
 </>;
}
function CreatorCard({creator:c,saved,onSave,onOpen}:{creator:Creator;saved:boolean;onSave:(id:string)=>void;onOpen:(c:Creator)=>void}){return <article className="creator-card"><div className="creator-photo" style={{background:c.color}}><button className="creator-open-photo" onClick={()=>onOpen(c)} aria-label={`عرض ملف ${c.name}`}><img src={c.image} alt={`صورة توضيحية لملف ${c.name}`} loading="lazy"/></button><button className={`heart-btn ${saved?'is-saved':''}`} aria-pressed={saved} aria-label={saved?`إزالة ${c.name} من المحفوظات`:`حفظ ${c.name}`} onClick={()=>onSave(c.id)}><Heart size={18} fill={saved?'currentColor':'none'}/></button><span className="creator-type">{c.category==='تصوير ومونتاج'?<Camera size={12}/>:<Video size={12}/>} {c.category==='تصوير ومونتاج'?'خلف الكاميرا':'صانع محتوى'}</span></div><div className="creator-info"><div className="creator-name-row"><button onClick={()=>onOpen(c)}>{c.name}</button><span><MapPin size={12}/>{c.city}</span></div><p>{c.role}</p><div className="skill-tags">{c.skills.slice(0,2).map(s=><span key={s}>{s}</span>)}</div><div className="creator-card-footer"><span>اكتشف أسلوبه الإبداعي</span><button className="arrow-button" onClick={()=>onOpen(c)} aria-label={`تفاصيل ${c.name}`}><ArrowUpLeft size={19}/></button></div></div></article>}

function FAQ(){const[open,setOpen]=useState<number|null>(0);const items=[['شو الفرق بين لقطة والتواصل المباشر مع صانع محتوى؟','لقطة تنظّم الحملة كاملة: الفكرة، اختيار الفريق، الاتفاق على نطاق العمل، متابعة التنفيذ، المراجعات والتسليم. بتتابع كل التفاصيل من لوحة واحدة، مع تحديد واضح للمخرجات والتعديلات.'],['لازم يكون عندي فكرة جاهزة للإعلان؟','لا. احكيلنا عن علامتك، جمهورك، والهدف من الإعلان. بعد مراجعة الطلب بنطوّر معك الفكرة، وبنبدأ التنفيذ بعد الاتفاق على الخطة والعرض.'],['هل سعر الباقة يشمل الإعلان المموّل وأتعاب المواهب؟','الأسعار المعروضة استرشادية للإنتاج حسب نطاق الباقة. ميزانية الإعلان المموّل، أتعاب المواهب والتنقّل تُذكر بشكل منفصل في العرض النهائي قبل أي التزام. لا يوجد دفع إلكتروني في هذه النسخة.'],['مين بملك المحتوى بعد التسليم؟','حقوق الاستخدام، مدتها، القنوات المسموحة، وتسليم الملفات الأصلية يتم توثيقها في اتفاق كل حملة قبل بدء الإنتاج. عرض الباقة وحده لا ينقل حقوقًا تلقائيًا.'],['هل المواهب والملفات المعروضة حقيقية؟','هذه نسخة أولية. الملفات والأسماء والصور في كتالوج المواهب أمثلة توضيحية، ولا تعني أن أصحاب الصور شركاء أو متاحون للحجز. طلبات الانضمام والحملات التي ترسلها من حسابك تُحفظ فعليًا للمراجعة.']];return <section className="faq-section container" id="faq"><div><span className="overline">قبل ما نبدأ</span><h2>يمكن خطرت <br/>ببالك هالأسئلة.</h2><p>وضوح من أول خطوة.</p></div><div className="faq-list">{items.map(([q,a],i)=><article className={open===i?'faq-item expanded':'faq-item'} key={q}><button aria-expanded={open===i} aria-controls={`faq-${i}`} onClick={()=>setOpen(open===i?null:i)}><span>{q}</span><Plus size={19}/></button><div id={`faq-${i}`} hidden={open!==i}><p>{a}</p></div></article>)}</div></section>}

function ModalShell({title,subtitle,children,onClose,wide=false}:{title:string;subtitle?:string;children:ReactNode;onClose:()=>void;wide?:boolean}){
 const ref=useRef<HTMLDivElement>(null);const closeRef=useRef(onClose);closeRef.current=onClose;
 useEffect(()=>{const prior=document.activeElement as HTMLElement;const overflow=document.body.style.overflow;document.body.style.overflow='hidden';const el=ref.current;const elements=()=>Array.from(el?.querySelectorAll<HTMLElement>('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]')||[]).filter(e=>!e.hasAttribute('hidden'));elements()[0]?.focus();function key(e:KeyboardEvent){if(e.key==='Escape')closeRef.current();if(e.key==='Tab'){const all=elements();const first=all[0],last=all[all.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}}document.addEventListener('keydown',key);return()=>{document.body.style.overflow=overflow;document.removeEventListener('keydown',key);prior?.focus();};},[]);
 return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><div ref={ref} className={`modal ${wide?'modal-wide':''}`} role="dialog" aria-modal="true" aria-labelledby="modal-title"><div className="modal-heading"><div><h2 id="modal-title">{title}</h2>{subtitle&&<p>{subtitle}</p>}</div><button className="icon-btn close-btn" aria-label="إغلاق النافذة" onClick={onClose}><X size={21}/></button></div>{children}</div></div>
}
function CreatorModal({creator:c,saved,onSave,onClose,onStart}:{creator:Creator;saved:boolean;onSave:(s:string)=>void;onClose:()=>void;onStart:()=>void}){return <ModalShell title="تعرّف على الأسلوب." subtitle="أفكار تستحق تكون جزءًا من حكايتك." onClose={onClose} wide><div className="creator-profile"><div className="profile-portrait"><img src={c.image} alt={`صورة ملف ${c.name} التوضيحي`}/><span className="demo-pill">ملف توضيحي</span></div><div className="profile-content"><div className="profile-name"><h3>{c.name}</h3><button className={`icon-btn ${saved?'coral-text':''}`} aria-label="حفظ الموهبة" aria-pressed={saved} onClick={()=>onSave(c.id)}><Heart fill={saved?'currentColor':'none'} size={22}/></button></div><p className="muted">{c.role}</p><span className="location"><MapPin size={15}/>{c.city}، فلسطين</span><p className="profile-bio">{c.bio}</p><div className="skill-tags">{c.skills.map(s=><span key={s}>{s}</span>)}</div><h4>اتجاه بصري مقترح</h4><div className="portfolio-preview"><img src={c.cover} alt="صورة مرجعية توضّح نوع المحتوى، وليست عملًا منسوبًا لصاحب الملف"/><span>مرجع بصري • صورة توضيحية</span></div></div></div><div className="callout"><ShieldCheck size={19}/><p>هذا ملف تجريبي باسم افتراضي وصورة توضيحية. اختيارك يُسجَّل كتفضيل للأسلوب، والفريق الفعلي يُقترح بعد مراجعة حملتك.</p></div><button className="btn btn-coral full" onClick={onStart}>أريد هذا الأسلوب لحملتي <ArrowUpLeft size={18}/></button></ModalShell>}

type Draft={title:string;business:string;category:string;city:string;brief:string;packageId:string;budget:number;date:string;creatorId:string|null;consent:boolean};
function CampaignWizard({packageId,creatorId,user,profile,mutate,onClose,onDone}:{packageId:string;creatorId:string|null;user:UserInfo;profile:Workspace['profile'];mutate:(v:Record<string,unknown>)=>Promise<unknown>;onClose:()=>void;onDone:()=>void}){
 const[step,setStep]=useState(0);const[busy,setBusy]=useState(false);const[error,setError]=useState('');const[restored,setRestored]=useState(false);
 const[draft,setDraft]=useState<Draft>({title:'',business:profile?.business||'',category:'مطاعم وكافيهات',city:profile?.city||'نابلس',brief:'',packageId,budget:packages.find(p=>p.id===packageId)?.price||1450,date:'',creatorId,consent:false});
 const formRef=useRef<HTMLFormElement>(null);
 useEffect(()=>{try{const previous=JSON.parse(sessionStorage.getItem('loqtah-brief')||'null');if(previous&&typeof previous.title==='string'){setDraft({...previous,packageId,budget:packages.find(p=>p.id===packageId)?.price||1450,creatorId,consent:false});setRestored(true);}}catch{}},[packageId,creatorId]);
 useEffect(()=>{sessionStorage.setItem('loqtah-brief',JSON.stringify(draft));},[draft]);
 function set<K extends keyof Draft>(key:K,value:Draft[K]){setDraft(d=>({...d,[key]:value}));setError('');}
 const pkg=packages.find(p=>p.id===draft.packageId)||packages[1];
 async function next(e:FormEvent){e.preventDefault();setError('');if(!formRef.current?.reportValidity())return;if(step===1&&!draft.date){setError('اختر موعد التسليم المفضّل.');return;}if(step<2){setStep(step+1);return;}setBusy(true);try{await mutate({action:'campaign',...draft});sessionStorage.removeItem('loqtah-brief');onDone();}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 return <ModalShell title="حملتك الجاية تبدأ هون." subtitle="تفاصيل بسيطة تساعدنا نفهم حكايتك." onClose={onClose} wide><div className="wizard-steps">{['عن علامتك','التفاصيل والباقة','مراجعة الطلب'].map((label,i)=><div className={step===i?'current':step>i?'done':''} key={label}><span>{step>i?<Check size={14}/>:i+1}</span>{label}</div>)}</div><form ref={formRef} onSubmit={next}>
 {restored&&step===0&&<div className="subtle-note">استعدنا مسودة طلبك من هذه الجلسة. تقدر تعدّلها قبل الإرسال.</div>}
 {step===0&&<div className="form-grid"><Field label="اسم العلامة أو المحل"><input required minLength={2} maxLength={100} autoComplete="organization" value={draft.business} onChange={e=>set('business',e.target.value)} placeholder="مثلًا: قهوة الحارة"/></Field><Field label="عنوان الحملة"><input required minLength={3} maxLength={100} value={draft.title} onChange={e=>set('title',e.target.value)} placeholder="مثلًا: إطلاق القائمة الشتوية"/></Field><Field label="مجال العلامة"><select value={draft.category} onChange={e=>set('category',e.target.value)}>{categories.slice(1).map(c=><option key={c}>{c}</option>)}</select></Field><Field label="مدينة التصوير"><select value={draft.city} onChange={e=>set('city',e.target.value)}>{cities.map(c=><option key={c}>{c}</option>)}</select></Field><Field label="احكيلنا عن الفكرة والهدف" full><textarea rows={4} required minLength={20} maxLength={3000} value={draft.brief} onChange={e=>set('brief',e.target.value)} placeholder="شو المنتج أو الخدمة؟ مين جمهورك؟ وشو حاب يحقق الإعلان؟ (20 حرفًا على الأقل)"/><small>{draft.brief.length} / 3000</small></Field></div>}
 {step===1&&<><div className="wizard-packages">{packages.map(p=><button type="button" className={p.id===draft.packageId?'selected':''} key={p.id} onClick={()=>{set('packageId',p.id);set('budget',p.price);}}><span className="radio-circle">{p.id===draft.packageId&&<span/>}</span><b>{p.name}</b><small>من {money(p.price)} ₪</small></button>)}</div><div className="form-grid"><Field label="الميزانية التقديرية (شيكل)"><input type="number" required min={300} max={100000} step={1} value={draft.budget} onChange={e=>set('budget',Number(e.target.value))}/></Field><Field label="موعد التسليم المفضّل"><input type="date" required min={new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Hebron'})} value={draft.date} onInput={e=>set('date',e.currentTarget.value)} onChange={e=>set('date',e.target.value)}/></Field><Field label="أسلوب الموهبة المفضّل" full><select value={draft.creatorId||''} onChange={e=>set('creatorId',e.target.value||null)}><option value="">رشّحوا لي الفريق المناسب</option>{creators.map(c=><option key={c.id} value={c.id}>{c.name} — أسلوب توضيحي</option>)}</select></Field></div><div className="callout"><Clock size={18}/><p>الموعد والميزانية تفضيلات أولية. نؤكد الجدول، الفريق والتكلفة النهائية معك قبل التنفيذ.</p></div></>}
 {step===2&&<><div className="brief-summary"><div><span className="overline">ملخّص الحكاية</span><h3>{draft.title}</h3><p>{draft.business} · {draft.city}</p></div><dl><div><dt>الباقة</dt><dd>{pkg.name}</dd></div><div><dt>الميزانية المقترحة</dt><dd>{money(draft.budget)} ₪</dd></div><div><dt>الموعد المفضّل</dt><dd>{draft.date&&dateLabel(draft.date)}</dd></div><div><dt>المجال</dt><dd>{draft.category}</dd></div></dl><p className="summary-body">{draft.brief}</p></div><label className="checkbox-label"><input type="checkbox" required checked={draft.consent} onChange={e=>set('consent',e.target.checked)}/><span>أوافق على إرسال بيانات الطلب للمراجعة. أفهم أن الطلب لا يؤكّد حجزًا ولا يترتّب عليه دفع، وأن العرض وحقوق الاستخدام يُتَّفق عليهما قبل التنفيذ.</span></label>{!user&&<div className="callout"><User size={19}/><div><p>سجّل دخولك لإرسال الطلب. مسودّتك محفوظة في هذه الجلسة.</p><a className="text-link" href="/signin-with-chatgpt?return_to=/%23campaign" target="_top">تسجيل الدخول باستخدام ChatGPT <ArrowUpLeft size={15}/></a></div></div>}</>}
 {error&&<p className="form-error" role="alert">{error}</p>}<div className="wizard-footer"><button type="button" className="btn btn-outline" onClick={()=>step?setStep(step-1):onClose()}><ArrowRight size={16}/>{step?'رجوع':'إلغاء'}</button><span>خطوة {step+1} من 3</span><button type="submit" className="btn btn-coral" disabled={busy||(step===2&&!user)}>{busy?<Loader2 className="spin" size={17}/>:step===2?'أرسل طلب الحملة':'الخطوة الجاية'}{!busy&&<ArrowLeft size={16}/>}</button></div></form></ModalShell>
}

function Field({label,children,full=false}:{label:string;children:ReactNode;full?:boolean}){return <label className={`field ${full?'field-full':''}`}><span>{label}</span>{children}</label>}
function Breadcrumb({title,home}:{title:string;home:()=>void}){return <div className="breadcrumb"><button onClick={home}>الرئيسية</button><ChevronLeft size={13}/><span>{title}</span></div>}
function Empty({icon,title,description,action,actionText}:{icon:ReactNode;title:string;description:string;action?:()=>void;actionText?:string}){return <div className="empty-state"><span className="empty-icon">{icon}</span><h3>{title}</h3><p>{description}</p>{action&&<button className="btn btn-dark" onClick={action}>{actionText}<ArrowUpLeft size={16}/></button>}</div>}

function Dashboard({user,workspace,loading,error,refresh,onNew,onOpen,navigate,auth}:{user:UserInfo;workspace:Workspace;loading:boolean;error:string;refresh:()=>void;onNew:()=>void;onOpen:(c:Campaign)=>void;navigate:(s:string)=>void;auth:()=>void}){
 const[tab,setTab]=useState('all');const active=workspace.campaigns.filter(c=>!['completed','cancelled'].includes(c.status));const review=workspace.campaigns.filter(c=>c.status==='review');
 const campaigns=workspace.campaigns.filter(c=>tab==='all'||(tab==='active'?!['completed','cancelled'].includes(c.status):c.status===tab));
 return <section className="container workspace-page"><Breadcrumb title="مساحة العمل" home={()=>navigate('home')}/><div className="section-heading"><div><span className="overline">كل مشهد، تحت عينك</span><h1 className="page-title">أهلًا {workspace.profile?.name?.split(' ')[0]|| (user?'في مساحتك':'في لقطة')}<span className="coral-text">.</span></h1><p>من أول طلب لآخر تسليم، كل تفاصيل حملاتك هون.</p></div><div className="heading-actions"><button className="icon-btn" aria-label="تحديث الحملات" onClick={refresh}><RefreshCw size={18} className={loading?'spin':''}/></button><button className="btn btn-coral" onClick={onNew}>حملة جديدة <Plus size={18}/></button></div></div>
 <div className="stats-grid">{[{icon:Clapperboard,value:workspace.campaigns.length,label:'كل الحملات',tone:'peach'},{icon:Camera,value:active.length,label:'حملات قيد العمل',tone:'lavender'},{icon:CheckCircle2,value:review.length,label:'بانتظار موافقتك',tone:'sage'},{icon:Heart,value:workspace.favorites.length,label:'مواهب محفوظة',tone:'sand'}].map(i=><div className="stat-card" key={i.label}><span className={`stat-icon ${i.tone}`}><i.icon size={22}/></span><strong>{i.value}</strong><span>{i.label}</span></div>)}</div>
 {workspace.isAdmin&&<button className="admin-link" onClick={()=>navigate('admin')}><ShieldCheck size={18}/> فتح لوحة إدارة لقطة <ArrowLeft size={16}/></button>}
 {workspace.application&&<div className="callout"><CheckCircle2 size={19}/><p>طلب انضمامك باسم <b>{workspace.application.name}</b>: {workspace.application.status==='approved'?'مقبول':workspace.application.status==='rejected'?'لم تتم الموافقة عليه':'قيد المراجعة'}. قبول الطلب لا ينشر ملفك تلقائيًا.</p></div>}
 <div className="workspace-list-header"><h2>حملاتك</h2><div className="workspace-tabs">{[['all','الكل'],['active','قيد العمل'],['completed','مكتملة']].map(([id,label])=><button key={id} className={tab===id?'active':''} onClick={()=>setTab(id)}>{label}</button>)}</div></div>
 {!user?<Empty icon={<LayoutDashboard/>} title="مساحة مرتّبة لكل أفكارك" description="سجّل دخولك لإنشاء حملتك الأولى ومتابعة التقدّم والملاحظات والتسليمات." action={auth} actionText="سجّل دخولك وابدأ"/>:error?<div className="error-panel" role="alert"><p>{error}</p><button className="btn btn-outline" onClick={refresh}>حاول مجددًا <RefreshCw size={16}/></button></div>:loading?<div className="loading-state"><Loader2 className="spin"/> نحمّل حملاتك…</div>:campaigns.length?<div className="campaign-list">{campaigns.map(c=><button className="campaign-row" key={c.id} onClick={()=>onOpen(c)}><span className="campaign-symbol"><Clapperboard size={24}/></span><div className="campaign-row-title"><b>{c.title}</b><small>{c.business} · {c.city}</small></div><span className={`status-badge status-${c.status}`}>{statusLabels[c.status]}</span><span className="campaign-date"><Calendar size={14}/>{dateLabel(c.date)}</span><ChevronLeft size={19}/></button>)}</div>:<Empty icon={<Clapperboard/>} title={tab==='all'?'أول حملة، أول حكاية.':'ما في حملات بهالقائمة'} description={tab==='all'?'احكيلنا عن علامتك وخلي فكرتك تاخد أول خطوة.':'أي حملة تطابق هذه الحالة رح تظهر هون.'} action={tab==='all'?onNew:()=>setTab('all')} actionText={tab==='all'?'أنشئ أول حملة':'عرض كل الحملات'}/>}
 <div className="workspace-tip"><span><Sparkles size={23}/></span><div><h3>الفكرة مش لازم تكون كاملة.</h3><p>احكيلنا شو بدّك تحقق، وبنرتّب تفاصيل المحتوى معك قبل أي اتفاق.</p></div><button className="text-link" onClick={onNew}>نبدأ؟ <ArrowUpLeft size={17}/></button></div>
 </section>
}

function CampaignDetail({campaign:c,workspace,mutate,onClose,notify}:{campaign:Campaign;workspace:Workspace;mutate:(v:Record<string,unknown>)=>Promise<unknown>;onClose:()=>void;notify:(s:string,e?:boolean)=>void}){
 const[tab,setTab]=useState('overview');const[message,setMessage]=useState('');const[busy,setBusy]=useState(false);const[error,setError]=useState('');const[feedback,setFeedback]=useState<Record<string,string>>({});const[confirmCancel,setConfirmCancel]=useState(false);
 const files=workspace.deliverables.filter(d=>d.campaignId===c.id);const chat=workspace.messages.filter(m=>m.campaignId===c.id);const stage=stages.indexOf(c.status as typeof stages[number]);
 async function action(data:Record<string,unknown>,success:string){setBusy(true);setError('');try{await mutate(data);notify(success);if(data.action==='message')setMessage('');if(data.action==='cancel')setConfirmCancel(false);}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 return <ModalShell title={c.title} subtitle={`${c.business} · ${c.city} · #${c.id.slice(0,8)}`} onClose={onClose} wide><div className="detail-status"><span className={`status-badge status-${c.status}`}>{statusLabels[c.status]}</span><span>أنشئت في {dateLabel(c.createdAt)}</span></div>{c.status!=='cancelled'&&<div className="campaign-timeline">{stages.map((s,i)=><div key={s} className={i<=stage?'reached':''}><span>{i<stage?<Check size={13}/>:i+1}</span><small>{['مراجعة الطلب','الفكرة','الإنتاج','موافقتك','التسليم'][i]}</small></div>)}</div>}<div className="detail-tabs">{[['overview','تفاصيل الحملة'],['files',`التسليمات (${files.length})`],['chat',`المراسلات (${chat.length})`]].map(([id,label])=><button key={id} className={tab===id?'active':''} onClick={()=>setTab(id)}>{label}</button>)}</div>
 {tab==='overview'&&<><div className="brief-summary"><dl><div><dt>الباقة</dt><dd>{packages.find(p=>p.id===c.packageId)?.name}</dd></div><div><dt>الميزانية المقترحة</dt><dd>{money(c.budget)} ₪</dd></div><div><dt>الموعد المفضّل</dt><dd>{dateLabel(c.date)}</dd></div><div><dt>مجال المحتوى</dt><dd>{c.category}</dd></div></dl><h4>فكرة الحملة</h4><p className="summary-body">{c.brief}</p></div><div className="callout"><ShieldCheck size={18}/><p>طلبك محفوظ. بدء التنفيذ والجدول والسعر النهائي يحتاجون اتفاقًا منفصلًا. لا يوجد دفع إلكتروني في هذه النسخة.</p></div>{c.status==='requested'&&(confirmCancel?<div className="cancel-confirm"><p>متأكد من سحب طلب الحملة؟ سيبقى في سجلك بحالة «ملغاة».</p><button disabled={busy} className="btn btn-danger" onClick={()=>action({action:'cancel',campaignId:c.id},'تم سحب طلب الحملة.')}>نعم، اسحب الطلب</button><button className="btn btn-outline" onClick={()=>setConfirmCancel(false)}>احتفظ بالطلب</button></div>:<button className="danger-link" onClick={()=>setConfirmCancel(true)}>سحب طلب الحملة</button>)}</>}
 {tab==='files'&&(files.length?<div className="deliverables">{files.map(f=><article className="deliverable" key={f.id}><div className="deliverable-heading"><span className="file-icon"><Video/></span><div><h3>{f.title}</h3><small>{f.status==='approved'?'تمت الموافقة':f.status==='changes'?'تعديلات مطلوبة':'بانتظار مراجعتك'}</small></div><a className="icon-btn" href={f.url} target="_blank" rel="noopener noreferrer" aria-label={`فتح ${f.title}`}><ExternalLink size={19}/></a></div>{f.feedback&&<p className="file-feedback">ملاحظتك: {f.feedback}</p>}{!['completed','cancelled'].includes(c.status)&&<><label className="field"><span>ملاحظاتك على هذه النسخة</span><textarea rows={2} maxLength={2000} value={feedback[f.id]||''} onChange={e=>setFeedback({...feedback,[f.id]:e.target.value})} placeholder="حدّد التعديلات المطلوبة بوضوح…"/></label><div className="deliverable-actions"><button disabled={busy} className="btn btn-dark" onClick={()=>action({action:'feedback',deliverableId:f.id,status:'approved',feedback:feedback[f.id]||''},'تم تسجيل موافقتك على المحتوى.')}>الموافقة على المحتوى <Check size={16}/></button><button disabled={busy||!feedback[f.id]?.trim()} className="btn btn-outline" onClick={()=>action({action:'feedback',deliverableId:f.id,status:'changes',feedback:feedback[f.id]},'تم إرسال طلب التعديل.')}>طلب تعديل</button></div></>}</article>)}</div>:<Empty icon={<ImageIcon/>} title="المشهد لسه قيد التجهيز" description="بعد الاتفاق والإنتاج، يضيف الفريق روابط المحتوى هون لتراجعه وتوافق عليه."/>)}
 {tab==='chat'&&<><div className="chat-messages">{chat.length?chat.map(m=><article key={m.id} className={`chat-bubble ${m.isTeam?'team':''}`}><div><b>{m.isTeam?'فريق لقطة':m.authorName}</b><time>{new Intl.DateTimeFormat('ar-PS',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(m.createdAt)}</time></div><p>{m.body}</p></article>):<div className="chat-empty"><MessageCircle size={30}/><p>عندك تفصيل أو سؤال عن حملتك؟ اكتبه هون.</p></div>}</div>{c.status!=='cancelled'&&<form className="chat-composer" onSubmit={e=>{e.preventDefault();void action({action:'message',campaignId:c.id,body:message},'تم إرسال رسالتك.');}}><textarea required maxLength={2000} rows={2} placeholder="اكتب رسالتك لفريق الحملة…" aria-label="رسالتك" value={message} onChange={e=>setMessage(e.target.value)}/><button className="btn btn-coral" disabled={busy||!message.trim()} type="submit" aria-label="إرسال الرسالة"><Send size={19}/></button></form>}</>}
 {error&&<p className="form-error" role="alert">{error}</p>}</ModalShell>
}

function JoinForm({user,application,mutate,onClose,onDone}:{user:UserInfo;application:Workspace['application'];mutate:(v:Record<string,unknown>)=>Promise<unknown>;onClose:()=>void;onDone:()=>void}){
 const[busy,setBusy]=useState(false);const[error,setError]=useState('');
 async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);setBusy(true);setError('');try{await mutate({action:'apply',name:f.get('name'),city:f.get('city'),category:f.get('category'),portfolio:f.get('portfolio'),bio:f.get('bio'),phone:f.get('phone'),consent:f.get('consent')==='on'});onDone();}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 return <ModalShell title="موهبتك إلها مكان هون." subtitle="احكيلنا عنك، وخلّي أعمالك تحكي الباقي." onClose={onClose} wide>{application?<Empty icon={<CheckCircle2/>} title="طلبك موجود معنا" description="يمكنك متابعة حالة طلب انضمامك من لوحة حملاتك. لا تحتاج لإرساله مرة ثانية."/>:!user?<div className="auth-content"><span className="auth-icon"><Camera size={32}/></span><p>سجّل دخولك أولًا، وبعدها احكيلنا عن موهبتك وأعمالك. طلبك يظل خاصًا حتى يراجعه فريق لقطة.</p><a className="btn btn-dark full" href="/signin-with-chatgpt?return_to=/%23join" target="_top">المتابعة باستخدام ChatGPT <ArrowUpLeft size={18}/></a></div>:<form onSubmit={submit}><div className="form-grid"><Field label="الاسم الكامل"><input name="name" defaultValue={user?.name||''} required minLength={2} maxLength={100} autoComplete="name" placeholder="اسمك اللي بتحب يعرفوك فيه"/></Field><Field label="رقم التواصل"><input name="phone" required minLength={7} maxLength={30} type="tel" autoComplete="tel" placeholder="05x xxx xxxx" dir="ltr"/></Field><Field label="مدينتك"><select name="city">{cities.map(c=><option key={c}>{c}</option>)}</select></Field><Field label="مجالك الأساسي"><select name="category">{categories.slice(1).map(c=><option key={c}>{c}</option>)}</select></Field><Field label="رابط معرض أعمالك أو حسابك المهني" full><input name="portfolio" required type="url" maxLength={1500} placeholder="https://instagram.com/your-work" dir="ltr" pattern="https://.*"/></Field><Field label="احكيلنا عن أسلوبك وخبرتك" full><textarea name="bio" required minLength={20} maxLength={2000} rows={3} placeholder="نوع المحتوى اللي بتحب تشتغله، خبرتك، وشو بيميّز أسلوبك…"/></Field></div><label className="checkbox-label"><input type="checkbox" name="consent" required/><span>أوافق على مراجعة فريق لقطة لبياناتي والتواصل معي بخصوص الانضمام. لن يُنشر ملفي قبل مراجعة منفصلة.</span></label>{error&&<p className="form-error" role="alert">{error}</p>}{user?<button type="submit" disabled={busy} className="btn btn-coral full">{busy?<Loader2 size={18} className="spin"/>:'أرسل طلب الانضمام'}<ArrowUpLeft size={18}/></button>:<div className="callout"><User size={18}/><div><p>تحتاج تسجيل الدخول قبل إرسال طلب الانضمام.</p><a className="text-link" target="_top" href="/signin-with-chatgpt?return_to=/%23dashboard">تسجيل الدخول باستخدام ChatGPT <ArrowUpLeft size={15}/></a></div></div>}</form>}</ModalShell>
}

function SettingsView({user,workspace,mutate,notify,auth}:{user:UserInfo;workspace:Workspace;mutate:(v:Record<string,unknown>)=>Promise<unknown>;notify:(s:string,e?:boolean)=>void;auth:()=>void}){
 const[busy,setBusy]=useState(false);
 async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);setBusy(true);try{await mutate({action:'profile',name:f.get('name'),business:f.get('business'),phone:f.get('phone'),city:f.get('city')});notify('تم حفظ بيانات حسابك.');}catch(e){notify((e as Error).message,true);}finally{setBusy(false);}}
 return <section className="container workspace-page"><span className="overline">خلّينا نتعرّف عليك</span><h1 className="page-title">إعدادات حسابك.</h1>{!user?<Empty icon={<User/>} title="مساحتك الشخصية" description="سجّل دخولك لتحدّث بياناتك وتخصّص مساحة عملك." action={auth} actionText="تسجيل الدخول"/>:<div className="settings-card"><div className="settings-identity"><span className="large-avatar">{(workspace.profile?.name||user.name).slice(0,1)}</span><div><h2>{workspace.profile?.name||user.name}</h2><p dir="ltr">{user.email}</p></div></div><form onSubmit={submit} key={JSON.stringify(workspace.profile)}><div className="form-grid"><Field label="الاسم"><input name="name" autoComplete="name" required minLength={2} maxLength={100} defaultValue={workspace.profile?.name||user.name}/></Field><Field label="اسم العلامة أو المحل"><input name="business" autoComplete="organization" maxLength={100} defaultValue={workspace.profile?.business||''}/></Field><Field label="رقم التواصل"><input name="phone" type="tel" maxLength={30} autoComplete="tel" defaultValue={workspace.profile?.phone||''} dir="ltr"/></Field><Field label="المدينة"><select name="city" defaultValue={workspace.profile?.city||'نابلس'}>{cities.map(c=><option key={c}>{c}</option>)}</select></Field></div><button disabled={busy} className="btn btn-coral" type="submit">{busy?<Loader2 className="spin" size={17}/>:<Check size={17}/>} حفظ التعديلات</button></form><div className="settings-signout"><span>تسجيل الدخول مرتبط بحسابك في ChatGPT.</span><a href="/signout-with-chatgpt?return_to=/" target="_top"><LogOut size={16}/> تسجيل الخروج</a></div></div>}</section>
}

function LegalModal({kind,onClose}:{kind:'terms'|'privacy';onClose:()=>void}){return <ModalShell title={kind==='privacy'?'خصوصيتك في لقطة.':'اتفاق واضح من البداية.'} onClose={onClose}><div className="legal-copy"><p className="subtle-note">سياسة تشغيل أولية للنسخة التجريبية — آخر تحديث: 5 نوفمبر 2026.</p>{kind==='privacy'?<><h3>ما الذي نحفظه؟</h3><p>هوية تسجيل الدخول والبريد الإلكتروني، بيانات الملف التي تضيفها، طلبات الحملات، المراسلات، ملاحظات المحتوى وطلبات انضمام صنّاع المحتوى. تُستخدم البيانات لتشغيل مساحة العمل ومراجعة الطلبات.</p><h3>الوصول للبيانات</h3><p>يُعزل سجل كل حساب عن الحسابات الأخرى. فريق الإدارة المصرّح له يستطيع مراجعة الطلبات والمراسلات لتنفيذ الخدمة. لا تعرض المنصة بياناتك الشخصية للعامة تلقائيًا.</p><h3>على جهازك</h3><p>نحتفظ بتفضيلات الحفظ للزائر في متصفحه، ومسودة طلب الحملة في جلسة التصفح إلى أن يرسلها أو ينهي الجلسة. يستخدم تسجيل الدخول ملفات الجلسة التي تديرها خدمة الاستضافة.</p><h3>الاحتفاظ والحذف</h3><p>هذه نسخة خاصة للتجربة. لا ترسل بيانات حساسة أو محتوى سريًا. طلب تصحيح أو حذف السجلات يُتابع مع مشغّل المنصة مباشرة. يلزم اعتماد سياسة الاحتفاظ وقنوات التواصل قبل الإطلاق العام.</p></>:<><h3>طبيعة هذه النسخة</h3><p>لقطة نسخة أولية لتنظيم طلبات إنتاج المحتوى. كتالوج المواهب توضيحي بأسماء افتراضية وصور مرجعية، ولا يثبت شراكة أو توافر أصحاب الصور.</p><h3>الطلبات والتسعير</h3><p>إرسال طلب حملة لا يمثّل عقدًا أو حجزًا أو التزامًا بالدفع. الأسعار تقديرية. نطاق العمل والفريق والمواعيد والتكلفة والتعديلات تُعتمد باتفاق منفصل قبل التنفيذ.</p><h3>المحتوى وحقوق الاستخدام</h3><p>يشترط امتلاك صلاحية استخدام المواد التي ترسلها. تُحدَّد حقوق النشر والإعلانات المموّلة ومدة الاستخدام والملفات الأصلية وموافقات الأشخاص في اتفاق الحملة. لا يُضمن عدد مشاهدات أو مبيعات.</p><h3>النسخة التجريبية</h3><p>لا يوجد دفع إلكتروني. استخدام مساحة العمل لا يضمن قبول طلب أو بدء خدمة. لا تُرفع مواد خاصة ضمن روابط تسليم عامة.</p></>}</div></ModalShell>}

function AdminView({enabled,notify}:{enabled:boolean;notify:(s:string,e?:boolean)=>void}){
 const[data,setData]=useState<{campaigns:Campaign[];applications:{id:string;name:string;city:string;category:string;portfolio:string;bio:string;phone:string;status:string}[];messages:Workspace['messages'];deliverables:Workspace['deliverables']}>({campaigns:[],applications:[],messages:[],deliverables:[]});const[error,setError]=useState('');const[busy,setBusy]=useState(false);const[selected,setSelected]=useState('');
 const load=useCallback(async()=>{if(!enabled)return;try{const r=await fetch('/api/admin');const d=await r.json() as typeof data & {error?:string};if(!r.ok)throw new Error(d.error);setData(d);}catch(e){setError((e as Error).message);}},[enabled]);useEffect(()=>{void load()},[load]);
 async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget;const f=new FormData(form);const body=Object.fromEntries(f.entries());setBusy(true);try{const r=await fetch('/api/admin',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json() as {error?:string};if(!r.ok)throw new Error(d.error);notify('تم حفظ تحديث الإدارة.');form.reset();await load();}catch(e){notify((e as Error).message,true);}finally{setBusy(false);}}
 return <section className="container workspace-page"><span className="overline">تشغيل لقطة</span><h1 className="page-title">لوحة الإدارة.</h1>{!enabled?<Empty icon={<ShieldCheck/>} title="هذه المساحة لفريق لقطة" description="صلاحية الإدارة تُمنح على الخادم لحسابات محددة فقط."/>:<><p className="muted">راجع الطلبات، حدّث مرحلة الإنتاج، وأضف روابط آمنة للتسليمات.</p>{error&&<p className="form-error">{error}</p>}<div className="admin-grid"><section className="settings-card"><h2>الحملات ({data.campaigns.length})</h2><label className="field"><span>الحملة</span><select value={selected} onChange={e=>setSelected(e.target.value)}><option value="">اختر حملة</option>{data.campaigns.map(c=><option key={c.id} value={c.id}>{c.business}: {c.title} — {statusLabels[c.status]}</option>)}</select></label>{selected&&<><div className="callout"><p>{data.campaigns.find(c=>c.id===selected)?.brief}</p></div><form onSubmit={submit}><input type="hidden" name="action" value="status"/><input type="hidden" name="campaignId" value={selected}/><Field label="المرحلة التالية"><select name="status">{stages.map(s=><option key={s} value={s}>{statusLabels[s]}</option>)}</select></Field><button disabled={busy} className="btn btn-dark">تحديث المرحلة</button></form><hr/><form onSubmit={submit}><input type="hidden" name="action" value="deliverable"/><input type="hidden" name="campaignId" value={selected}/><Field label="اسم التسليم"><input name="title" required minLength={2} maxLength={100}/></Field><Field label="رابط HTTPS للمحتوى"><input name="url" required type="url" pattern="https://.*" dir="ltr"/></Field><button disabled={busy} className="btn btn-dark">إضافة تسليم <Plus size={16}/></button></form><hr/><h3 className="admin-subheading">التسليمات والملاحظات</h3>{data.deliverables.filter(f=>f.campaignId===selected).map(f=><article key={f.id} className="admin-file"><a className="text-link" href={f.url} target="_blank" rel="noopener noreferrer">{f.title} <ExternalLink size={14}/></a><p>{f.status==='approved'?'موافق عليه':f.status==='changes'?'تعديلات مطلوبة':'بانتظار الموافقة'}</p>{f.feedback&&<p>ملاحظة العميل: {f.feedback}</p>}<form onSubmit={submit}><input type="hidden" name="action" value="revise"/><input type="hidden" name="campaignId" value={selected}/><input type="hidden" name="deliverableId" value={f.id}/><input type="hidden" name="title" value={f.title}/><Field label="رابط النسخة المعدّلة"><input name="url" type="url" required pattern="https://.*" dir="ltr" placeholder="https://…"/></Field><button disabled={busy} className="btn btn-outline">إعادة الإرسال للموافقة</button></form></article>)}<hr/><h3 className="admin-subheading">مراسلات الحملة</h3><div className="admin-messages">{data.messages.filter(m=>m.campaignId===selected).map(m=><div key={m.id}><b>{m.isTeam?'فريق لقطة':m.authorName}</b><p>{m.body}</p></div>)}</div><form onSubmit={submit}><input type="hidden" name="action" value="message"/><input type="hidden" name="campaignId" value={selected}/><Field label="رسالة من الفريق"><textarea required name="body" maxLength={2000}/></Field><button disabled={busy} className="btn btn-dark">إرسال للعميل <Send size={15}/></button></form></>}</section><section className="settings-card"><h2>طلبات انضمام المواهب ({data.applications.length})</h2>{data.applications.map(a=><article className="admin-application" key={a.id}><h3>{a.name}</h3><p>{a.city} · {a.category} · {a.status}</p><p>{a.bio}</p><p dir="ltr">{a.phone}</p><a href={a.portfolio} target="_blank" rel="noopener noreferrer" className="text-link">معرض الأعمال <ExternalLink size={14}/></a><form onSubmit={submit}><input type="hidden" name="action" value="application"/><input type="hidden" name="id" value={a.id}/><select name="status" defaultValue={a.status}><option value="pending">قيد المراجعة</option><option value="approved">مقبول</option><option value="rejected">مرفوض</option></select><button disabled={busy} className="btn btn-outline">حفظ</button></form></article>)}{!data.applications.length&&<p className="muted">لم يصل أي طلب بعد.</p>}</section></div></>}</section>
}
